// Validates the canonical JSON the oracle reads, so a renamed key or a dangling id stops the run with its cause
// instead of shrinking the set of props compared.

/** The canonical JSON shape this oracle reads (`SCHEMA_VERSION` in crates/core/src/types/output.rs). */
export const SUPPORTED_SCHEMA_VERSION = 6

/** Throws unless `caliper` has the keys the oracle reads, at the schema version it understands. */
export function checkCaliperShape(caliper: any): void {
  if (caliper?.schemaVersion !== SUPPORTED_SCHEMA_VERSION) {
    throw new Error(
      `caliper output has schemaVersion ${JSON.stringify(caliper?.schemaVersion)}, the oracle reads ${SUPPORTED_SCHEMA_VERSION}`,
    )
  }
  for (const key of ['components', 'propSets', 'props'] as const) {
    if (typeof caliper[key] !== 'object' || caliper[key] === null) {
      throw new Error(`caliper output has no "${key}" object`)
    }
  }
}

/** One map of prop name to prop id for a component, merged from the prop sets it lists. */
export function flattenProps(caliper: any, componentKey: string, component: any): Record<string, string> {
  if (!Array.isArray(component.props)) return component.props
  const merged: Record<string, string> = {}
  for (const id of component.props) {
    const set = caliper.propSets[id]
    if (set === undefined) throw new Error(`component ${componentKey} lists prop set ${id}, which propSets lacks`)
    Object.assign(merged, set)
  }
  return merged
}

/** Throws when a comparison compared nothing, which a gate must not report as clean. */
export function requireComparison(propsShared: number, componentsMatched: number): void {
  if (propsShared === 0) {
    throw new Error(`the comparison is empty: ${componentsMatched} components matched, 0 shared props compared`)
  }
}
/** The canonical JSON schema version the oracle reads (ADR 0017). A Rust test compares it with `SCHEMA_VERSION`. */
export const SUPPORTED_SCHEMA_VERSION = 6

/** Returns `output` once its `schemaVersion` is the supported one and throws otherwise. Output without a version predates it. */
export function assertSchemaVersion<T extends { schemaVersion?: number }>(output: T, what: string): T {
  const version = output.schemaVersion ?? 1
  if (version !== SUPPORTED_SCHEMA_VERSION) {
    throw new Error(
      `The ${what} has schema version ${version}, and the oracle reads version ${SUPPORTED_SCHEMA_VERSION}. ` +
        'Run it with a caliper-docgen binary of the same release.',
    )
  }
  return output
}
import { describe, expect, it } from 'vitest'
import { caliperNorm } from '../src/caliper-norm.ts'
import { compare, prim } from '../src/oracle-compare.ts'
import { checkCaliperShape, flattenProps, requireComparison } from '../src/caliper-input.ts'

const good = { schemaVersion: 6, components: {}, propSets: {}, props: {} }

describe('the oracle input checks', () => {
  it('a renamed propSets key stops the run naming the key', () => {
    expect.hasAssertions()
    const { propSets, ...renamed } = { ...good, prop_sets: {} }
    void propSets
    expect(() => checkCaliperShape(renamed)).toThrow('caliper output has no "propSets" object')
  })

  it('a schema version the oracle does not read stops the run', () => {
    expect.hasAssertions()
    expect(() => checkCaliperShape({ ...good, schemaVersion: 3 })).toThrow(
      'caliper output has schemaVersion 3, the oracle reads 6',
    )
    expect(() => checkCaliperShape({ components: {} })).toThrow('has schemaVersion undefined')
  })

  it('a prop set id that propSets lacks names the component and the id', () => {
    expect.hasAssertions()
    expect(() => flattenProps({ propSets: { a: { x: 'p1' } } }, 'Button', { props: ['a', 'gone'] })).toThrow(
      'component Button lists prop set gone, which propSets lacks',
    )
    expect(flattenProps({ propSets: { a: { x: 'p1' }, b: { y: 'p2' } } }, 'Button', { props: ['a', 'b'] })).toEqual({
      x: 'p1',
      y: 'p2',
    })
  })

  it('a comparison of zero shared props throws instead of reading clean', () => {
    expect.hasAssertions()
    expect(() => requireComparison(0, 12)).toThrow('the comparison is empty: 12 components matched, 0 shared props')
    expect(() => requireComparison(3, 1)).not.toThrow()
  })

  it('optional and rest parameters Caliper records are not scored less precise', () => {
    expect.hasAssertions()
    const fn = (optional: boolean, rest: boolean) =>
      caliperNorm({
        kind: 'function',
        params: [{ name: 'a', type: { kind: 'string' }, optional, rest }],
        returnType: { kind: 'void' },
      })
    const checker = {
      k: 'function' as const,
      params: [{ optional: true, rest: false, type: prim('string') }],
      returns: prim('void'),
    }
    expect(compare(fn(true, false), checker)).toBe('identical')
    expect(compare(fn(false, false), checker)).toBe('less precise')
  })
})
import { describe, expect, it } from 'vitest'
import { assertSchemaVersion, SUPPORTED_SCHEMA_VERSION } from '../src/schema-version.ts'

describe('assertSchemaVersion', () => {
  it('returns output of the supported version', () => {
    const output = { schemaVersion: SUPPORTED_SCHEMA_VERSION, components: {} }
    expect(assertSchemaVersion(output, 'caliper JSON')).toBe(output)
  })

  it('rejects another version, naming both', () => {
    expect(() => assertSchemaVersion({ schemaVersion: 99 }, 'caliper JSON')).toThrow(
      `The caliper JSON has schema version 99, and the oracle reads version ${SUPPORTED_SCHEMA_VERSION}. ` +
        'Run it with a caliper-docgen binary of the same release.',
    )
  })

  it('treats output without a version as version 1', () => {
    expect(() => assertSchemaVersion({}, 'caliper JSON')).toThrow('has schema version 1,')
  })
})
