// A tool's canonical JSON (Caliper's `extract --json`) as the independent reference reads it: the type it gives a prop,
// or whether a collapsed inheritance layer names the prop, which surfaces it without a type to judge.
import { readFileSync, realpathSync } from 'node:fs'
import { relative } from 'node:path'
import { layerMembers, listedProps } from './canonical.ts'
import { caliperNorm } from './caliper-norm.ts'
import { type Norm } from './oracle-compare.ts'
import { normComponent } from './tool-universe.ts'

interface Located {
  name: string
  component: any
}

export interface Tool {
  /** Whether the tool reports exactly one component of that name in that file. */
  has(file: string, component: string): boolean
  /** What the tool says of `prop` of `component` in `file`. `found` is false when it has no single component of that name
   * there. Otherwise `norm` is the prop's type when the component lists it, as its own prop or a curated inherited one
   * (the own prop wins a clash), and `layered` says a collapsed layer names it, which surfaces it without a type. */
  lookup(file: string, component: string, prop: string): { found: boolean; norm?: Norm; layered: boolean }
}

export function loadTool(path: string, root: string): Tool {
  const caliper = JSON.parse(readFileSync(path, 'utf8'))
  const base = realpathSync(root)
  const byFile = new Map<string, Located[]>()
  for (const component of Object.values<any>(caliper.components)) {
    const key = relative(base, realpathSync(component.filePath))
    byFile.set(key, [...(byFile.get(key) ?? []), { name: normComponent(component.displayName), component }])
  }
  const single = (file: string, name: string) => {
    const matches = (byFile.get(file) ?? []).filter((c) => c.name === normComponent(name))
    return matches.length === 1 ? matches[0].component : undefined
  }
  return {
    has: (file, component) => single(file, component) !== undefined,
    lookup(file, componentName, prop) {
      const component = single(file, componentName)
      if (component === undefined) return { found: false, layered: false }
      const id = listedProps(caliper, component)[prop]
      const layered = (component.inheritance ?? []).some((layer: any) => layerMembers(caliper, layer).includes(prop))
      const type = id === undefined ? undefined : caliper.props[id]?.type
      return { found: true, norm: type === undefined ? undefined : caliperNorm(type), layered }
    },
  }
}
// The checker side of the independent reference: the exported components of one corpus, found the way
// src/oracle.ts finds them (src/checker-components.ts), and each own prop of each as a `Candidate`
// (src/reference-sample.ts) with what is cheap to know about it. Nothing here judges a type.
import { realpathSync } from 'node:fs'
import { relative } from 'node:path'
import { ObjectFlags, SignatureKind, TypeFlags } from 'typescript-beta/sync'
import { declaredExports, exportName, propsTypeOf } from './checker-components.ts'
import {
  keyOf,
  seeded,
  shuffled,
  type Candidate,
  type Origin,
  type PropsShape,
  type ValueKind,
} from './reference-sample.ts'
import { normComponent, pathKey } from './tool-universe.ts'

/** A prop the checker found, with what judging it needs. */
export interface Entry {
  candidate: Candidate
  symbol: any
  type: any
  /** Named by the list the run was given, not drawn for the control sample. */
  listed: boolean
}

export interface Universe {
  checker: any
  project: any
  entries: Entry[]
  /** How many exported components with at least one prop the control sample is drawn from: those `accept` lets through,
   * or every one when it is not given. A listed prop of another component is in `entries` but not counted here. */
  components: number
}

export interface CollectOptions {
  checker: any
  project: any
  corpus: string
  root: string
  /** Keys (`keyOf`) of the props the run was told to judge. */
  wanted: Set<string>
  /** Stop adding control-sample candidates once this many are collected; listed props are always kept. */
  cap: number
  seed: string
  /** Whether a component is one a reader sees. The checker takes any one-parameter function for a component (a style
   * helper, a context), so with a tool's output given the control sample is drawn from the components the tool reports.
   * Listed props are kept either way. */
  accept?: (file: string, component: string) => boolean
}

const GENERIC = TypeFlags.TypeParameter | TypeFlags.IndexedAccess | TypeFlags.Conditional | TypeFlags.Substitution
const LITERAL = TypeFlags.StringLiteral | TypeFlags.NumberLiteral | TypeFlags.BooleanLiteral | TypeFlags.EnumLiteral
const UTILITIES = new Set(['Pick', 'Omit', 'Partial', 'Required', 'Readonly', 'Record'])
// Per component, so one component's hundreds of DOM attributes do not stand for the corpus.
const HTML_PER_COMPONENT = 3

function shapeOf(propsType: any): PropsShape {
  if (propsType.flags & TypeFlags.Intersection) return 'intersection'
  const alias = propsType.getAliasSymbol()?.name
  const mapped = propsType.flags & TypeFlags.Object && propsType.objectFlags & ObjectFlags.Mapped
  return mapped || (alias && UTILITIES.has(alias)) ? 'mapped' : 'plain'
}

function originOf(declaration: string | undefined, file: string): Origin {
  if (declaration === undefined) return 'own'
  const path = pathKey(declaration)
  if (path.includes('/@types/react/')) return 'html'
  if (path.includes('/node_modules/')) return 'dependency'
  return path === pathKey(file) ? 'own' : 'extends'
}

/** What a prop's type is, from the checker's flags and, for a union or object, its members' call signatures. */
function kindOf(checker: any, type: any): ValueKind {
  if (type.flags & GENERIC) return 'generic'
  const members: any[] = type.flags & TypeFlags.Union ? (type.getTypes() ?? []) : [type]
  if (members.some((m) => m.flags & GENERIC)) return 'generic'
  if (
    members.some((m) => m.flags & TypeFlags.Object && checker.getSignaturesOfType(m, SignatureKind.Call).length > 0)
  ) {
    return 'function'
  }
  return members.filter((m) => m.flags & LITERAL).length > 1 ? 'union_literal' : 'other'
}

/** Every own prop of the components in `files` as an entry. Files with listed props come first and are always read;
 * the rest, in a seeded order, until `cap` control candidates are collected. */
export function collect(files: string[], options: CollectOptions): Universe {
  const { checker, project } = options
  const root = realpathSync(options.root)
  const rel = (path: string) => relative(root, realpathSync(path))
  const random = seeded(options.seed)
  const withListed = new Set([...options.wanted].map((k) => k.split('\u0000')[0]))
  const ordered = [
    ...files.filter((f) => withListed.has(rel(f))),
    ...shuffled(
      files.filter((f) => !withListed.has(rel(f))),
      random,
    ),
  ]
  const entries: Entry[] = []
  let components = 0
  let control = 0
  for (const file of ordered) {
    const mustRead = withListed.has(rel(file))
    if (!mustRead && control >= options.cap) continue
    const moduleSymbol = checker.getSymbolOfSourceFile(file)
    if (!moduleSymbol) continue
    for (const exported of declaredExports(checker, moduleSymbol)) {
      let propsType
      try {
        propsType = propsTypeOf(checker, exported)
      } catch {
        continue
      }
      if (!propsType) continue
      const props = checker.getPropertiesOfType(propsType).filter((p: any) => p.name !== 'ref' && p.name !== 'key')
      if (props.length === 0) continue
      const name = exportName(checker, exported)
      const accepted = options.accept?.(rel(file), name) ?? true
      if (!accepted && !mustRead) continue
      if (accepted) components++
      const shape = shapeOf(propsType)
      const types = checker.getTypeOfSymbol(props)
      let html = 0
      for (const [i, p] of props.entries()) {
        const origin = originOf(p.declarations?.[0]?.path ? String(p.declarations[0].path) : undefined, file)
        const candidate: Candidate = {
          corpus: options.corpus,
          file: rel(file),
          component: name,
          prop: p.name,
          origin,
          shape,
          kind: kindOf(checker, types[i]),
        }
        const listed = options.wanted.has(keyOf({ ...candidate, component: normComponent(name) }))
        if (!listed && !accepted) continue
        if (!listed && origin === 'html' && ++html > HTML_PER_COMPONENT) continue
        entries.push({ candidate, symbol: p, type: types[i], listed })
        if (!listed) control++
      }
    }
  }
  return { checker, project, entries, components }
}
// What TypeScript 7.1's checker says about the questions in scripts/agent_questions.json, for scripts/agent_eval.py.
//
// The weekly agent evaluation asks what a reader of Caliper's output would answer about one component and compares that
// with the checker, never with Caliper itself. This script is the checker's side: for each question it finds the
// component's exported props type the way src/oracle.ts does and writes one fact per question id. A question the checker
// cannot answer (no such component, no such prop, a prop that is not a literal union) is `invalid`, which the evaluation
// reports apart from the answers it scores.
//
// usage: tsx src/agent-truth.ts --root DIR --tsconfig FILE --questions FILE --corpus NAME --out FILE
import { readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { API, SignatureKind, SymbolFlags, TypeFlags } from 'typescript-beta/sync'
import { exportName, propsTypeOf } from './checker-components.ts'

const KEYS = ['root', 'tsconfig', 'questions', 'corpus', 'out'] as const
const args: Partial<Record<(typeof KEYS)[number], string>> = {}
for (let i = 2; i < process.argv.length; i += 2) {
  args[process.argv[i].replace(/^--/, '') as (typeof KEYS)[number]] = process.argv[i + 1]
}
if (!args.root || !args.tsconfig || !args.questions || !args.corpus || !args.out) {
  console.error('usage: tsx src/agent-truth.ts --root DIR --tsconfig FILE --questions FILE --corpus NAME --out FILE')
  process.exit(2)
}

interface Question {
  id: string
  corpus: string
  kind: 'present' | 'prop_exists' | 'prop_required' | 'literal_values' | 'type_kind'
  file: string
  component: string
  prop?: string
}
type Truth = { value: boolean | string | string[] } | { invalid: string }

const root = realpathSync(args.root)
const questions = (JSON.parse(readFileSync(args.questions, 'utf8')).questions as Question[]).filter(
  (q) => q.corpus === args.corpus,
)
const absolute = (q: Question) => realpathSync(join(root, q.file))
const files = [...new Set(questions.map((q) => absolute(q)))]

const api = new API({ cwd: root })
// The component files only, with the tsconfig the oracle uses; the checker reads what they import on demand.
const { options } = api.parseConfigFile(args.tsconfig)
const program = api.createProgram(files, options)
const { checker } = program.getProject()

const without = (type: any) => checker.getNonNullableType(type)

/** What a reader of one prop's type could say about it, from the checker's type and not from its text. */
function kindOf(type: any): string {
  const t = without(type)
  if (t.flags & TypeFlags.Boolean) return 'boolean'
  if (t.flags & TypeFlags.String) return 'string'
  if (t.flags & TypeFlags.Number) return 'number'
  if (t.flags & TypeFlags.Union) {
    const members: any[] = t.getTypes() ?? []
    if (members.length > 0 && members.every((m) => m.flags & TypeFlags.StringLiteral)) return 'literal_union'
    return 'other'
  }
  if (t.flags & TypeFlags.StringLiteral) return 'literal_union'
  if (t.flags & TypeFlags.Object) {
    if (checker.isArrayType(t)) return 'array'
    const [sig] = checker.getSignaturesOfType(t, SignatureKind.Call)
    if (sig && checker.getPropertiesOfType(t).length === 0) return 'function'
  }
  return 'other'
}

function literalValues(type: any): string[] | undefined {
  const t = without(type)
  const members: any[] = t.flags & TypeFlags.Union ? (t.getTypes() ?? []) : [t]
  if (members.length === 0 || !members.every((m) => m.flags & TypeFlags.StringLiteral)) return undefined
  return members.map((m) => String(m.value)).toSorted()
}

function answer(q: Question): Truth {
  const moduleSymbol = checker.getSymbolOfSourceFile(absolute(q))
  if (!moduleSymbol) return { invalid: `the checker has no module for ${q.file}` }
  const exported = checker
    .getExportsOfModule(moduleSymbol)
    .find((e: any) => e.name === q.component || (e.name === 'default' && exportName(checker, e) === q.component))
  let props: any[] = []
  if (exported) {
    // A checker failure propagates to the caller's `the checker failed` fact instead of reading as no props.
    const propsType = propsTypeOf(checker, exported)
    props = propsType ? checker.getPropertiesOfType(propsType) : []
  }
  if (q.kind === 'present') return { value: props.length > 0 }
  if (props.length === 0) return { invalid: `the checker finds no component ${q.component} in ${q.file}` }
  const prop = props.find((p: any) => p.name === q.prop)
  if (q.kind === 'prop_exists') return { value: prop !== undefined }
  if (!prop) return { invalid: `the checker finds no prop ${q.prop} on ${q.component}` }
  if (q.kind === 'prop_required') return { value: !(prop.flags & SymbolFlags.Optional) }
  const type = checker.getTypeOfSymbol(prop)
  if (q.kind === 'type_kind') return { value: kindOf(type) }
  const values = literalValues(type)
  return values
    ? { value: values }
    : { invalid: `${q.prop} is ${checker.typeToString(type)}, not a string literal union` }
}

const truth: Record<string, Truth> = {}
for (const q of questions) {
  try {
    truth[q.id] = answer(q)
  } catch (error) {
    truth[q.id] = { invalid: `the checker failed: ${String(error).slice(0, 120)}` }
  }
}
writeFileSync(args.out, JSON.stringify(truth, null, 2))
program.dispose()
api.close()
console.error(`${questions.length} questions, ${files.length} files`)
// The name a default export is listed under, read from TypeScript 7.1's checker, which names the function type's symbol
// `default` and gives the declaration handle no name of its own.
import { mkdirSync, mkdtempSync, realpathSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { API } from 'typescript-beta/sync'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { declaredExports, exportName, propsTypeOf } from '../src/checker-components.ts'

const FILES: Record<string, string> = {
  'Badge.tsx': `export default function Badge(props: { label: string }) { return <span>{props.label}</span> }\n`,
  'Card.tsx': `const Card = (props: { title: string }) => <b>{props.title}</b>\nexport default Card\n`,
  'Panel.tsx': `export default class Panel { props!: { open: boolean } }\n`,
  'button-group.tsx': `export default function (props: { label: string }) { return <i>{props.label}</i> }\n`,
  'Wrapped.tsx': `export default (props: { label: string }) => <u>{props.label}</u>\n`,
